// Fanged Bite: you regain Hit Points equal to the Necrotic damage dealt by the Necrotic Save
// (the attack's other activity). Sangromancy Specialist also regains one spent Sangromancy Die.
const SANGROMANCY_SOURCE_UUID = "Compendium.transformations.gh-transformations.Item.qmepd5HkL0LpxOJv"
const { workflow } = args[0] ?? {}
const actor = workflow?.actor
if (!actor) return
let necrotic = 0
for (const entry of workflow.damageList ?? []) {
    for (const damage of entry?.damageDetails?.otherDamage ?? []) {
        const value = Number(damage?.value ?? 0)
        if (damage?.type === "necrotic" && value > 0) necrotic += value
    }
}
necrotic = Math.floor(necrotic)
if (necrotic <= 0) return
await actor.applyDamage([{ value: necrotic, type: "healing" }])
const sangromancy = actor.items.find(item => item.getFlag("transformations", "sourceUuid") === SANGROMANCY_SOURCE_UUID)
const spent = Number(sangromancy?.system?.uses?.spent ?? 0)
if (sangromancy && spent > 0) await sangromancy.update({ "system.uses.spent": spent - 1 })
